import { ErrorBoundary } from 'solid-js';

// ✅ NEW: <ErrorBoundary> isolates the error to the widget area.
// The rest of the application (navbar, sidebar) stays completely interactive.
export default function App() {
  return (
    <div>
      <nav>Navbar</nav>
      <main>
        <ErrorBoundary
          fallback={(err, reset) => (
            <div className="error-card">
              <p>Widget crashed: {err.message}</p>
              <button onClick={reset}>Try Again</button>
            </div>
          )}
        >
          <BuggyWidget />
        </ErrorBoundary>
      </main>
    </div>
  );
}
